package net.civeira.phylax.features.oauth.tokensecurity.infrastructure.driver;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.time.Instant;
import java.util.Date;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

import org.junit.jupiter.api.Test;

import com.auth0.jwt.JWT;
import com.auth0.jwt.algorithms.Algorithm;

import io.smallrye.jwt.auth.principal.JWTAuthContextInfo;
import io.smallrye.jwt.auth.principal.ParseException;
import net.civeira.phylax.features.oauth.tokensecurity.application.AccessTokenPolicy;
import net.civeira.phylax.features.oauth.tokensecurity.domain.gateway.TokenSigner;

/** The bearer factory rechecks audience and revocation on every parse, without a REST context. */
class TokenJwtCallerPrincipalFactoryUnitTest {
  @Test
  void rejectsWrongAudienceAndRevokedTokenAfterASuccessfulParse() throws Exception {
    String jwt = JWT.create().withIssuer("https://issuer/oauth/openid/acme").withSubject("alice")
        .withJWTId("jti-1").withExpiresAt(Date.from(Instant.now().plusSeconds(300)))
        .withClaim("typ", "Bearer").sign(Algorithm.HMAC256("test-only"));
    AccessTokenPolicy policy = mock(AccessTokenPolicy.class);
    TokenSigner signer = mock(TokenSigner.class);
    when(signer.verifiedKeypass("acme", jwt)).thenReturn("key-1");
    when(policy.validateEarly("acme", jwt, null)).thenReturn(Optional.of(Map.of("jti", "jti-1")),
        Optional.of(Map.of("jti", "jti-1")), Optional.empty());
    when(policy.validateEarly("acme", jwt, "resource-a")).thenReturn(Optional.empty(),
        Optional.of(Map.of("jti", "jti-1")));
    TokenJwtCallerPrincipalFactory factory = new TokenJwtCallerPrincipalFactory(signer, policy);
    JWTAuthContextInfo context = new JWTAuthContextInfo();
    context.setExpectedAudience(Set.of("resource-a"));

    assertThrows(ParseException.class, () -> factory.parse(jwt, context));
    assertEquals("alice", factory.parse(jwt, context).getSubject());
    assertThrows(ParseException.class, () -> factory.parse(jwt, context));
  }
}
